a73f83f fix: correct rollback guard and remove provider response snippets from errors
 internal/git/service.go       |  7 -------
 internal/git/service_test.go  | 21 ++++++++++++++-------
 internal/providers/helpers.go | 17 ++---------------
 3 files changed, 16 insertions(+), 29 deletions(-)
commit a73f83fc6171cb780b6be6a46b97b80b7a29b2fd
Author:     bytetrue <bytetrue@outlook.com>
AuthorDate: Mon May 25 01:46:36 2026 +0800
Commit:     bytetrue <bytetrue@outlook.com>
CommitDate: Mon May 25 01:46:36 2026 +0800

    fix: correct rollback guard and remove provider response snippets from errors

    finding-01: remove responseSnippet from executeJSONRequest error paths in
    helpers.go; the tool_call_provider.go path was already fixed in the prior
    commit.

    finding-02: revert overly aggressive pre-reset status guard. The guard
    blocked multi-commit transaction rollbacks because intermediate commits
    naturally change status. git reset --mixed does not touch the working tree,
    so a status difference does not indicate data loss. Restore the original
    post-reset status check which correctly reports rolled_back_with_status_change
    when the working tree diverged. Update the unit test to reflect the correct
    semantics: rollback succeeds and reports status change rather than refusing.

diff --git a/internal/git/service.go b/internal/git/service.go
index 9ac5c87..e876100 100644
--- a/internal/git/service.go
+++ b/internal/git/service.go
@@ -413,13 +413,6 @@ func RollbackCommitTransaction(cwd string, env map[string]string, snapshot Commi
 	if strings.TrimSpace(snapshot.Head) == "" {
 		return CommitTransactionRollbackResult{RolledBack: false, Status: "unsafe", Message: "missing transaction start head"}
 	}
-	statusBeforeReset := normalizeRunnerResult(gitRunner(cwd, []string{"status", "--porcelain=v1", "-z", "--untracked-files=all"}, env))
-	if statusBeforeReset.ExitCode != 0 {
-		return CommitTransactionRollbackResult{RolledBack: false, Status: "failed", Message: "rollback safety check failed"}
-	}
-	if statusBeforeReset.Stdout != snapshot.Status {
-		return CommitTransactionRollbackResult{RolledBack: false, Status: "unsafe", Message: "working tree changed since transaction start"}
-	}
 	resetResult := normalizeRunnerResult(gitRunner(cwd, []string{"reset", "--mixed", snapshot.Head}, env))
 	if resetResult.ExitCode != 0 {
 		return CommitTransactionRollbackResult{RolledBack: false, Status: "failed", Message: firstNonEmpty(resetResult.Stderr, resetResult.Stdout, "git reset failed")}
diff --git a/internal/providers/helpers.go b/internal/providers/helpers.go
index fbfd382..4472518 100644
--- a/internal/providers/helpers.go
+++ b/internal/providers/helpers.go
@@ -8,7 +8,6 @@ import (
 )

 const defaultMaxOutputTokens = 8192
-const responseSnippetLength = 500

 const (
 	defaultOpenAIBaseURL    = "https://api.openai.com/v1"
@@ -63,18 +62,6 @@ func applyUserAgent(request *http.Request, cfg ProviderConfig) {
 	}
 }

-func responseSnippet(body []byte) string {
-	serialized := strings.Join(strings.Fields(string(body)), " ")
-	runes := []rune(serialized)
-	if len(runes) > responseSnippetLength {
-		return string(runes[:responseSnippetLength]) + "…"
-	}
-	if serialized == "" {
-		return "<empty>"
-	}
-	return serialized
-}
-
 func executeJSONRequest(client HTTPDoer, request *http.Request, payload any, destination any) error {
 	body, err := json.Marshal(payload)
 	if err != nil {
@@ -91,10 +78,10 @@ func executeJSONRequest(client HTTPDoer, request *http.Request, payload any, des
 		return err
 	}
 	if response.StatusCode < 200 || response.StatusCode >= 300 {
-		return fmt.Errorf("http %d: %s", response.StatusCode, responseSnippet(responseBody))
+		return fmt.Errorf("http %d", response.StatusCode)
 	}
 	if err := json.Unmarshal(responseBody, destination); err != nil {
-		return fmt.Errorf("decode response: %w; snippet: %s", err, responseSnippet(responseBody))
+		return fmt.Errorf("decode response: %w", err)
 	}
 	return nil
 }

